def encrypt(s: str) -> str:
    """
    Encrypt a string by rotating each alphabetic character 4 places
    forward in the alphabet (wrapping around at 'z'/'Z').
    Non-alphabetic characters are left unchanged.
    """
    result = []

    for ch in s:
        if 'a' <= ch <= 'z':
            offset = (ord(ch) - ord('a') + 4) % 26
            result.append(chr(ord('a') + offset))
        elif 'A' <= ch <= 'Z':
            offset = (ord(ch) - ord('A') + 4) % 26
            result.append(chr(ord('A') + offset))
        else:
            result.append(ch)

    return ''.join(result)
